{
  "items": [
    {
      "name": "Int.div_two_lt_floor",
      "module_name": "Mathlib.Algebra.Order.Floor.Ring",
      "kind": "theorem",
      "type": "∀ {k : Type u_4} [inst : Field k] [inst_1 : LinearOrder k] [IsStrictOrderedRing k] [inst_3 : FloorRing k] {a : k},\n  1 ≤ a → a / 2 < ↑⌊a⌋"
    },
    {
      "name": "Int.log",
      "module_name": "Mathlib.Data.Int.Log",
      "kind": "definition",
      "type": "{R : Type u_1} → [inst : Semifield R] → [inst_1 : LinearOrder R] → [FloorSemiring R] → ℕ → R → ℤ"
    },
    {
      "name": "Real.natLog_le_logb",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Base",
      "kind": "theorem",
      "type": "∀ (a b : ℕ), ↑(Nat.log b a) ≤ Real.logb ↑b ↑a"
    },
    {
      "name": "Behrend.div_lt_floor",
      "module_name": "Mathlib.Combinatorics.Additive.AP.Three.Behrend",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, 2 / (1 - 2 / Real.exp 1) ≤ x → x / Real.exp 1 < ↑⌊x / 2⌋₊"
    },
    {
      "name": "harmonic_floor_le_one_add_log",
      "module_name": "Mathlib.NumberTheory.Harmonic.Bounds",
      "kind": "theorem",
      "type": "∀ (y : ℝ), 1 ≤ y → ↑(harmonic ⌊y⌋₊) ≤ 1 + Real.log y"
    },
    {
      "name": "log_le_harmonic_floor",
      "module_name": "Mathlib.NumberTheory.Harmonic.Bounds",
      "kind": "theorem",
      "type": "∀ (y : ℝ), 0 ≤ y → Real.log y ≤ ↑(harmonic ⌊y⌋₊)"
    },
    {
      "name": "Nat.clog_le_iff_le_pow",
      "module_name": "Mathlib.Data.Nat.Log",
      "kind": "theorem",
      "type": "∀ {b : ℕ}, 1 < b → ∀ {x y : ℕ}, Nat.clog b x ≤ y ↔ x ≤ b ^ y"
    },
    {
      "name": "Real.log_sqrt",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Basic",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, 0 ≤ x → Real.log √x = Real.log x / 2"
    }
  ]
}
